    pammViewTitle: "PAMM\u8CEC\u6236",
    pammViewSubTitle: "\u5C07\u8CC7\u91D1\u914D\u7F6E\u7D66\u7D93\u9A57\u8C50\u5BCC\u7684\u57FA\u91D1\u7D93\u7406",
    pammBoxSentence: "\u767E\u5206\u6BD4\u5206\u914D\u7BA1\u7406\u6A21\u584A\uFF08PAMM\uFF09\u2014 \u8207\u5C08\u696D\u4EA4\u6613\u54E1\u5171\u540C\u6295\u8CC7",
    pammBoxSentence1: "PAMM\uFF08Percentage Allocation Management Module\uFF0C\u767E\u5206\u6BD4\u5206\u914D\u7BA1\u7406\u6A21\u584A\uFF09\u5141\u8A31\u6295\u8CC7\u8005\u5C07\u8CC7\u91D1\u914D\u7F6E\u7D66\u5C08\u696D\u4EA4\u6613\u54E1\uFF08\u8CC7\u91D1\u7BA1\u7406\u4EBA\uFF09\u9032\u884C\u4EA4\u6613\u3002PAMM \u8CEC\u6236\u4E2D\u7684\u76C8\u8667\u5C07\u6309\u7167\u5404\u6295\u8CC7\u8005\u7684\u8CC7\u91D1\u5360\u6BD4\u9032\u884C\u5206\u914D\u3002",
    pammBoxSentence2: "\u7121\u9700\u89AA\u81EA\u7BA1\u7406\uFF0C\u5373\u53EF\u53C3\u8207\u5C08\u696D\u4EA4\u6613\u7B56\u7565",
    pammBoxSentence3: "\u901A\u904E\u591A\u5143\u5316\u7B56\u7565\u8207\u591A\u4F4D\u7BA1\u7406\u4EBA\u5BE6\u73FE\u6295\u8CC7\u5206\u6563",
    pammBoxSentence4: "\u900F\u660E\u7684\u7E3E\u6548\u8FFD\u8E64\u8207\u5831\u544A\u6A5F\u5236",
    pammBoxSentence5: "\u9748\u6D3B\u7684\u6295\u8CC7\u91D1\u984D\uFF0C\u591A\u6A23\u5316\u7684\u53C3\u8207\u9580\u6ABB",
    pammBoxSentence6: "\u7ACB\u5373\u958B\u59CB\u6295\u8CC7",
    pammBoxSentence7: "\u700F\u89BD\u4E86\u89E3\u5B8C\u6574\u6A5F\u5236 \u2014\u2014 \u67E5\u770B\u8CC7\u91D1\u5982\u4F55\u914D\u7F6E\u3001\u6536\u76CA\u5982\u4F55\u5206\u914D\u3002",
    pammBoxSentence8: "\u4E86\u89E3\u66F4\u591A",
    pammBox1Sentence: "PAMM\u904B\u4F5C\u6982\u89BD\uFF1A\u60A8\u7684\u8CC7\u91D1\u5982\u4F55\u88AB\u7BA1\u7406",
    pammBox1Sentence1: "\u4F5C\u70BA\u4E00\u7A2E\u8CC7\u91D1\u7BA1\u7406\u6A21\u5F0F\uFF0C\u6295\u8CC7\u8005\u53EF\u501F\u52A9\u5C08\u696D\u8CEC\u6236\u7BA1\u7406\u4EBA\u7684\u4EA4\u6613\u80FD\u529B\u5BE6\u73FE\u8CC7\u7522\u589E\u503C\u3002",
    pammBox1Sentence2: "PAMM\u7CFB\u7D71\u7684\u8CEC\u6236\u904B\u4F5C\u901A\u5E38\u7531\u4E3B\u8CEC\u6236\u8207\u5B50\u8CEC\u6236\u5171\u540C\u69CB\u6210\u3002",
