    pammBox1Sentence4: "\u4E3B\u8CEC\u6236\u767C\u51FA\u7684\u4EA4\u6613\u6307\u4EE4\u5C07\u540C\u6B65\u7531\u5B50\u8CEC\u6236\u57F7\u884C\u3002",
    pammBox2Sentence: "\u767E\u5206\u6BD4\u5206\u914D\u7BA1\u7406\u6A21\u584A\uFF08PAMM\uFF09\u2014 \u8207\u5C08\u696D\u4EA4\u6613\u54E1\u5171\u540C\u6295\u8CC7",
