    whyBoxSentence3: "\u591A\u8A9E\u8A00\u5BA2\u6236\u670D\u52D9",
    whyBox1Sentence: "\u9AD8\u6760\u687F",
    whyBox1Sentence1: "\u4F4E\u9EDE\u5DEE",
